import asyncio
import os

from agent_framework import Agent, Content, Message
from agent_framework.openai import OpenAIChatCompletionClient
from dotenv import load_dotenv
from openai import AsyncOpenAI

load_dotenv()
endpoint = os.getenv("AZURE_OPENAI_ENDPOINT")
apikey = os.getenv("AZURE_OPENAI_API_KEY")

openai_client = AsyncOpenAI(
    api_key=apikey,
    base_url=endpoint + "/openai/v1/",
    timeout=60,
)

# If you don't want to use the APIKey, you can use Bearer token authentication instead
# from azure.identity import DefaultAzureCredential, get_bearer_token_provider
# token_provider = get_bearer_token_provider(DefaultAzureCredential(), "https://ai.azure.com/.default")
# openai_client = AsyncOpenAI(
#     api_key=token_provider,
#     base_url=endpoint + "/openai/v1/",
#     timeout=60,
# )

agent = Agent(client=OpenAIChatCompletionClient(model="gpt-5", async_client=openai_client))

# You can use DevToys or any online tool to convert an image to base64
myimage = "data:image/jpeg;base64,"

MAGENTA = "\033[95m"
RESET = "\033[0m"


async def main() -> None:
    imageresponse = await agent.run(
        Message(
            role="user",
            contents=[
                Content.from_text("Can you analyze the image I am sending you and describe what you see in detail?"),
                Content.from_uri(uri=myimage, media_type="image/jpeg"),
                # You can also send the image as a Uri if it is hosted somewhere, just make sure the model has access to
                # that location (e.g. public url or accessible with the credentials you provide)
                # Content.from_uri(uri="https://example.com/image.jpg", media_type="image/jpeg"),
            ],
        )
    )
    print(imageresponse)

    usage = imageresponse.usage_details
    if usage:
        print(MAGENTA)
        print(f"Input Tokens: {usage.get('input_token_count')}")
        print(f"Cached Tokens: {usage.get('cache_read_input_token_count') or 0}")
        print(f"Output Tokens: {usage.get('output_token_count')}")
        print(f"Reasoning Tokens: {usage.get('reasoning_output_token_count') or 0}")
        print(f"Total Tokens: {usage.get('total_token_count')}", end="")
        print(RESET)


if __name__ == "__main__":
    asyncio.run(main())
